// Generate a possibly-valid cutlass::Status value. We allow any integral value to
// exercise both valid and invalid paths; the function must handle invalid values
// by returning "Invalid status".
unsigned int raw = *FUZZ_PARAM(unsigned int);
cutlass::Status status = static_cast<cutlass::Status>(raw);

// Call the target function; it returns a pointer to a static string literal.
char const *msg = cutlass::cutlassGetStatusString(status);

// Validate contract: returned pointer must be non-null and must not be freed/modified.
FUZZ_ASSERT(msg != nullptr, "cutlassGetStatusString must return non-null");
// No outputs to return; the pointer is to static storage.

// On host, this must always return false. On device, only thread 0 of block 0 returns true.
bool is_thread0 = cutlass::thread0();
// Host-side fuzzing environment expects false.
FUZZ_ASSERT(is_thread0 == false, "thread0() must be false on host");
// No persistent objects to output.

// Returns lane index within warp; on host fallback, returns 0.
int lane = cutlass::canonical_lane_idx();
// Lane must always be in [0, 31]. This holds both on device and host fallback.
FUZZ_ASSERT(lane >= 0 && lane < 32, "canonical_lane_idx must be in [0,31]");
// No persistent objects to output.

// Returns warp-uniform warp index; on host fallback, returns 0.
int warp_idx_sync = cutlass::canonical_warp_idx_sync();
// Index must be non-negative.
FUZZ_ASSERT(warp_idx_sync >= 0, "canonical_warp_idx_sync must be non-negative");
// No persistent objects to output.

// Returns warp index without synchronization; on host fallback, returns 0.
int warp_idx = cutlass::canonical_warp_idx();
// Index must be non-negative.
FUZZ_ASSERT(warp_idx >= 0, "canonical_warp_idx must be non-negative");
// No persistent objects to output.

// Returns warp-group (128-thread) index; on host fallback, returns 0.
int warp_group_idx = cutlass::canonical_warp_group_idx();
// Index must be non-negative.
FUZZ_ASSERT(warp_group_idx >= 0, "canonical_warp_group_idx must be non-negative");
// No persistent objects to output.
